content.query:
let appCount = 5;
let requestCount = 5;
let selectedApps = range i from 1 to 1 step 1
| extend x = '{Apps:name}'
| extend x = split(x, ', ')
| mvexpand x to typeof(string) limit 100
| project appName = x;
let topItems = AppRequests
| top-nested appCount of AppRoleName by AppMetric = countif(Success == false) desc, top-nested requestCount of Name by RequestMetric = countif(Success == false) desc;
let topApps = topItems | summarize by appName = AppRoleName;
let topRequests = topItems | summarize by strcat(AppRoleName, '::', Name);
let rawData = AppRequests
| extend name = iff(strcat(AppRoleName, '::', Name) in (topRequests), Name, 'Other Requests'), appName = iff(AppRoleName in (topApps), AppRoleName, 'Other Apps');
let apps = rawData
| summarize FailedRequests = countif(Success == false), AllRequests = count(), Users = dcount(UserId) by appName
| project Id = appName, ParentId = '', Name = strcat('☁️ ', appName), Kind = 'Application', FailedRequests, AllRequests, Users
| join kind = inner (
    rawData
    | make-series Trend = countif(Success == false) default = 0 on TimeGenerated from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain} by Id = appName
) on Id
| project-away Id1, TimeGenerated
| join kind = fullouter (selectedApps) on $left.Id == $right.appName
| extend Id = appName, Name = strcat('☁️ ', appName), Kind = 'Application', FailedRequests = iff(Id == '', 0, FailedRequests), AllRequests = iff(Id == '', 0, AllRequests), Users = iff(Id == '', 0, Users), Trend = iff(Id == '', repeat(0, toint(({TimeRange:end} - {TimeRange:start}) / {TimeRange:grain})), Trend);
let reqs = rawData
| summarize FailedRequests = countif(Success == false), AllRequests = count(), Users = dcount(UserId) by appName, name
| project Id = strcat(appName, '::', name), ParentId = appName, Name = strcat('🌐 ', name), Kind = 'Request', FailedRequests, AllRequests, Users
| join kind = inner (
    rawData
    | make-series Trend = countif(Success == false) default = 0 on TimeGenerated from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain} by Id = strcat(appName, '::', name)
) on Id
| project-away Id1, TimeGenerated;
reqs
| union (apps)
| extend Rank = iff(Name contains 'Other Apps' or Name contains 'Other Requests', 2, 1)
| order by Rank asc, FailedRequests desc
| project Id, ParentId, Name, Kind, ['Failed Requests'] = FailedRequests, ['Failed Request Trend'] = Trend, ['All Requests'] = AllRequests, ['Success Rate'] = 1.0 * (AllRequests - FailedRequests) / AllRequests, Users

